#include <bits/stdc++.h>
using namespace std;

int invnum(const std::vector<int>& sequence) {
    int count = 0;
    int len = sequence.size();
    for (int i = 0; i < len; ++i) {
        for (int j = i + 1; j < len; ++j) {
            if (sequence[i] > sequence[j]) {
                count++;
            }
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;

    // Using unordered_map for cache: cache[N][flag][k]
    // Since k can be negative, we use a map for each N and flag
    // For performance, we can store cache as vector of vector of map
    vector<vector<array<unordered_map<int, int>, 2>>> cache(n + 1, vector<array<unordered_map<int, int>, 2>>(n + 1));
    // cache[N][flag][k] -> int

    function<int(int, int, bool)> solve = [&](int N, int K, bool flag) -> int {
        int flag_idx = flag ? 1 : 0;
        if (cache[N][flag_idx][K].count(K)) {
            return cache[N][flag_idx][K];
        }
        if (N == 1) {
            int res = 0;
            if (!flag && K < 0) {
                res = 1;
            }
            cache[N][flag_idx][K] = res;
            return res;
        }
        int max_inv = N * (N - 1) / 2;
        if (K < -max_inv - 1) {
            int res = solve(N, -max_inv - 1, flag);
            cache[N][flag_idx][K] = res;
            return res;
        }
        if (K >= max_inv) {
            cache[N][flag_idx][K] = 0;
            return 0;
        }
        int total = 0;
        for (int delta = -N + 1; delta < N; ++delta) {
            if (flag && delta > 0) continue;
            int weight = min(N - delta, delta + N);
            int new_K = K - delta;
            bool new_flag = flag && (delta == 0);
            total += (long long)solve(N - 1, new_K, new_flag) * weight;
            total %= mod;
        }
        cache[N][flag_idx][K] = total;
        return total;
    };

    int result = solve(n, 0, true) % mod;
    cout << result << "\n";

    return 0;
}
